// Normalize whatever the placeholder source returned into a
// stable shape the rest of the pipeline (Script Generation, etc.)
// can rely on. No AI/inference happens here — this is pure
// data shaping, with safe fallbacks since the upstream source
// is currently a placeholder and may return nothing real.
const input = $input.first().json;
const rawResults = Array.isArray(input.raw_results) ? input.raw_results : [];

const normalized = rawResults.map((item, index) => {
  return {
    rank: index + 1,
    title: item.title ?? item.name ?? 'PLACEHOLDER_TITLE',
    summary: item.summary ?? item.description ?? 'PLACEHOLDER_SUMMARY',
    source: item.source ?? input.source_url ?? 'PLACEHOLDER_SOURCE',
    score: typeof item.score === 'number' ? item.score : null,
  };
});

// Guarantee at least one placeholder row so downstream
// sub-workflows (Script Generation) always receive a
// well-formed research_data array, even before a real
// trend source is wired in.
if (normalized.length === 0) {
  normalized.push({
    rank: 1,
    title: 'PLACEHOLDER_TITLE',
    summary: 'PLACEHOLDER_SUMMARY',
    source: 'PLACEHOLDER_SOURCE',
    score: null,
  });
}

return [{ json: { workflow_run_id: input.workflow_run_id ?? null, research_data: normalized } }];
